(3537251, 496065, 69487, '<td valign="top">Friggen Icelandics....... 9 You know I love it!</td>', 'Friggen Icelandics....... 9 You know I love it!', '2007-04-11 01:08:14.000000', NULL, 1),
(3537257, 495497, 69487, '<td valign="top">Camera in mirror mode?</td>', 'Camera in mirror mode?', '2007-04-11 01:09:31.000000', NULL, 1),
(3537260, 496075, 29906, '<td valign="top">Excellent shot and incredible colors.</td>', 'Excellent shot and incredible colors.', '2007-04-11 01:10:29.000000', NULL, 1),
(3537263, 496055, 50583, '<td valign="top">Nice butt ;) Me want to touch.</td>', 'Nice butt ;) Me want to touch.', '2007-04-11 01:11:15.000000', NULL, 1),
(3537264, 496051, 29906, '<td valign="top">Wow, great shot.</td>', 'Wow, great shot.', '2007-04-11 01:11:54.000000', NULL, 1),
(3537271, 495681, 29906, '<td valign="top">This is going straight into my favorites. Excellent shot.</td>', 'This is going straight into my favorites. Excellent shot.', '2007-04-11 01:13:07.000000', NULL, 1),
(3537272, 495564, 67844, '<td valign="top">I am going to guess that this is about a 8 minute exposure. Nice job making the night look almost exactly like daytime + stars.</td>', 'I am going to guess that this is about a 8 minute exposure. Nice job making the night look almost exactly like daytime + stars.', '2007-04-11 01:13:07.000000', NULL, 1),
(3537274, 496057, 16402, '<td valign="top">Excellent, very big feel.</td>', 'Excellent, very big feel.', '2007-04-11 01:13:21.000000', NULL, 1),
(3537277, 495588, 67844, '<td valign="top">The yellow light, which I am assuming is the moon, and the light on top of each tower are a little too bright.</td>', 'The yellow light, which I am assuming is the moon, and the light on top of each tower are a little too bright.', '2007-04-11 01:15:06.000000', NULL, 1),
(3537279, 494940, 50583, '<td valign="top">It''s....blue....very strange.</td>', 'It''s....blue....very strange.', '2007-04-11 01:15:15.000000', NULL, 1),
(3537287, 495681, 50583, '<td valign="top">Dirty river??  Nice shot though.</td>', 'Dirty river??  Nice shot though.', '2007-04-11 01:17:18.000000', NULL, 1),
(3537292, 496118, 50583, '<td valign="top">Sorry, I just don''t like this shot.  Nothing interesting in the foreground.</td>', 'Sorry, I just don''t like this shot.  Nothing interesting in the foreground.', '2007-04-11 01:18:11.000000', NULL, 1),
(3537297, 494741, 71657, '<td valign="top">whats this?</td>', 'whats this?', '2007-04-11 01:18:48.000000', NULL, 1),
(3537306, 495597, 50583, '<td valign="top">Are you serious??</td>', 'Are you serious??', '2007-04-11 01:19:58.000000', NULL, 1),
(3537311, 495649, 67844, '<td valign="top">The fire looks ... well sort of ... blotchy. Maybe due to over saturation?</td>', 'The fire looks ... well sort of ... blotchy. Maybe due to over saturation?', '2007-04-11 01:20:31.000000', NULL, 1),
(3537324, 494741, 50583, '<td valign="top">Too dark.  Please be conisiderate of different types of monitors.</td>', 'Too dark.  Please be conisiderate of different types of monitors.', '2007-04-11 01:22:51.000000', NULL, 1),
(3537337, 496065, 49315, '<td valign="top">Im sorry but I am so over this shots!</td>', 'Im sorry but I am so over this shots!', '2007-04-11 01:25:02.000000', NULL, 1),
(3537342, 496052, 49315, '<td valign="top">Sorry But I am so over these shots</td>', 'Sorry But I am so over these shots', '2007-04-11 01:25:57.000000', NULL, 1),
(3537371, 492880, 39430, '<td valign="top">They let you take a photo at night on the deck of an aircraft carrier?  Wow!</td>', 'They let you take a photo at night on the deck of an aircraft carrier?  Wow!', '2007-04-11 01:31:54.000000', NULL, 1),
(3537372, 494335, 39430, '<td valign="top">Might be nicer if the light was in focus</td>', 'Might be nicer if the light was in focus', '2007-04-11 01:32:17.000000', NULL, 1),
(3537375, 496112, 39430, '<td valign="top">Not quite in focus.  The red border doesn''t help this image at all.</td>', 'Not quite in focus.  The red border doesn''t help this image at all.', '2007-04-11 01:33:02.000000', NULL, 1),
(3537377, 495639, 15711, '<td valign="top">Yippeeeeeeee.</td>', 'Yippeeeeeeee.', '2007-04-11 01:33:14.000000', NULL, 1),
(3537380, 495095, 39430, '<td valign="top">The perspective distortion is a bit much though, and I''d prefer to see less black sky, and more foreground.  Other than that, it''s nice postcard image.</td>', 'The perspective distortion is a bit much though, and I''d prefer to see less black sky, and more foreground.  Other than that, it''s nice postcard image.', '2007-04-11 01:34:15.000000', NULL, 1),
(3537384, 495351, 39430, '<td valign="top">Boats are lost in the gloom a little.  This would have been really cool if you could have somehow lit a flash on each boat.</td>', 'Boats are lost in the gloom a little.  This would have been really cool if you could have somehow lit a flash on each boat.', '2007-04-11 01:35:25.000000', NULL, 1),
(3537390, 492936, 39430, '<td valign="top">These light trails photos seldom catch my interest.  Nice colours and balance, but not for me.</td>', 'These light trails photos seldom catch my interest.  Nice colours and balance, but not for me.', '2007-04-11 01:36:48.000000', NULL, 1),
(3537395, 495663, 39430, '<td valign="top">Dramatic capture.  With the gold light on the statue, you could probably have pushed the colour balance further to deepen the blue sky more.  Great shot though.</td>', 'Dramatic capture.  With the gold light on the statue, you could probably have pushed the colour balance further to deepen the blue sky more.  Great shot though.', '2007-04-11 01:37:56.000000', NULL, 1),
(3537399, 494547, 39430, '<td valign="top">Lacks a little contrast, but nice colours.</td>', 'Lacks a little contrast, but nice colours.', '2007-04-11 01:38:35.000000', NULL, 1),
(3537402, 493610, 39430, '<td valign="top">I like the light trail along the road.  Was this planned?</td>', 'I like the light trail along the road.  Was this planned?', '2007-04-11 01:39:20.000000', NULL, 1),
(3537406, 495827, 15266, '<td valign="top">Wow, feel like I''ve been there.  ;)   <br/> <br/>It looks great!</td>', 'Wow, feel like I''ve been there.  ;)    It looks great!', '2007-04-11 01:39:53.000000', NULL, 1),
(3537422, 495521, 65069, '<td valign="top">off camera lighting?</td>', 'off camera lighting?', '2007-04-11 01:41:49.000000', NULL, 1),
(3537428, 496090, 65069, '<td valign="top">rotate canvas clockwise and crop...small issue, but i have OCD.</td>', 'rotate canvas clockwise and crop...small issue, but i have OCD.', '2007-04-11 01:42:56.000000', NULL, 1),
(3537431, 495594, 39430, '<td valign="top">It''s very hard to photograph night shots without getting this nasty orange look to them.  White balance is always worth a try, maybe even using raw to get more control over it.</td>', 'It''s very hard to photograph night shots without getting this nasty orange look to them.  White balance is always worth a try, maybe even using raw to get more control over it.', '2007-04-11 01:43:32.000000', NULL, 1),
(3537435, 496127, 39430, '<td valign="top">Nice city scape.  Pity the 640 pixels really limits the size of panorama photos.</td>', 'Nice city scape.  Pity the 640 pixels really limits the size of panorama photos.', '2007-04-11 01:44:20.000000', NULL, 1),
(3537454, 493289, 74663, '<td valign="top">very crisp clean and inviting... I lost my breath when it came up -8-</td>', 'very crisp clean and inviting... I lost my breath when it came up -8-', '2007-04-11 01:49:29.000000', NULL, 1),
(3537456, 496073, 74663, '<td valign="top">very unique view... maybe a little too much usm -7-</td>', 'very unique view... maybe a little too much usm -7-', '2007-04-11 01:50:10.000000', NULL, 1),
(3537459, 495390, 73981, '<td valign="top">I took a shot of the the same kind only from the bridge behind you I believe. I''m trying to figure out what part of the walkway you are on (Closer to Midosuji or Sakaisuji). Nice shot</td>', 'I took a shot of the the same kind only from the bridge behind you I believe. I''m trying to figure out what part of the walkway you are on (Closer to Midosuji or Sakaisuji). Nice shot', '2007-04-11 01:50:14.000000', NULL, 1),
(3537463, 492997, 39430, '<td valign="top">Try using longer exposures for fireworks, to get the trails of the lights.  It will also allow to bump the saturation for richer colours.</td>', 'Try using longer exposures for fireworks, to get the trails of the lights.  It will also allow to bump the saturation for richer colours.', '2007-04-11 01:50:34.000000', NULL, 1),
(3537465, 494809, 74663, '<td valign="top">I hope this ribbons - everything works, your use of the rule of thirds is great.... I can feel the emotion your trying to convey. I dont like the border IMO ... regardless -8-</td>', 'I hope this ribbons - everything works, your use of the rule of thirds is great.... I can feel the emotion your trying to convey. I dont like the border IMO ... regardless -8-', '2007-04-11 01:51:57.000000', NULL, 1),
(3537470, 495436, 39430, '<td valign="top">Nice crisp image.  I''d probably opt for a more standard 2x3 crop to get rid of the dead space at the sides.  Would be better without the wires across the image.  A sky full of bright stars would be great too, but that would probably require contrast mapping and advanced editing.  :)</td>', 'Nice crisp image.  I''d probably opt for a more standard 2x3 crop to get rid of the dead space at the sides.  Would be better without the wires across the image.  A sky full of bright stars would be great too, but that would probably require contrast mapping and advanced editing.  :)', '2007-04-11 01:53:10.000000', NULL, 1),
(3537474, 495856, 39430, '<td valign="top">Contrast is a bit lacking.  I''m not sure whether the BW does it justice either.  Would be nice to see the original colour version.</td>', 'Contrast is a bit lacking.  I''m not sure whether the BW does it justice either.  Would be nice to see the original colour version.', '2007-04-11 01:54:33.000000', NULL, 1),
(3537477, 495681, 39430, '<td valign="top">Nice bright colours and a sharp image.  Maybe overdone though?</td>', 'Nice bright colours and a sharp image.  Maybe overdone though?', '2007-04-11 01:55:11.000000', NULL, 1),
(3537488, 496043, 39430, '<td valign="top">Some noise reduction wouldn''t go astray.  :)  Actually, I''d really like to see this one tone-mapped in advanced editing to bring out some more detail.  But, we can''t do that in Basic.</td>', 'Some noise reduction wouldn''t go astray.  :)  Actually, I''d really like to see this one tone-mapped in advanced editing to bring out some more detail.  But, we can''t do that in Basic.', '2007-04-11 01:57:30.000000', NULL, 1),
(3537492, 496140, 39430, '<td valign="top">Would be nicer without the orange cast.  Changing the white balance would help fix this, and also give a richer blue sky.</td>', 'Would be nicer without the orange cast.  Changing the white balance would help fix this, and also give a richer blue sky.', '2007-04-11 01:59:08.000000', NULL, 1),
(3537496, 494542, 39430, '<td valign="top">It''s bright and colourful, but there''s nothing that grabs my attention.</td>', 'It''s bright and colourful, but there''s nothing that grabs my attention.', '2007-04-11 02:00:02.000000', NULL, 1),
(3537510, 496065, 39430, '<td valign="top">Wow.  Pity we can''t all live in iceland!  :)  It''s a bit too, ah, what''s the word, oh yeah, Green.  :)  If it wasn''t basic editing, I''d like to see the mountains stark BW, with this awesome sky above.</td>', 'Wow.  Pity we can''t all live in iceland!  :)  It''s a bit too, ah, what''s the word, oh yeah, Green.  :)  If it wasn''t basic editing, I''d like to see the mountains stark BW, with this awesome sky above.', '2007-04-11 02:02:15.000000', NULL, 1),
(3537519, 494188, 39430, '<td valign="top">Close the aperture and use a longer shutter.  You''ll get smoother reflections, and nice neat stars around the lights.  Still, it''s a nice image as it is.</td>', 'Close the aperture and use a longer shutter.  You''ll get smoother reflections, and nice neat stars around the lights.  Still, it''s a nice image as it is.', '2007-04-11 02:03:56.000000', NULL, 1),
(3537523, 495928, 39430, '<td valign="top">It''s come out a little dark.  You couldn''t really expose more, because the fountain would blowout, but maybe a closer view would be better?</td>', 'It''s come out a little dark.  You couldn''t really expose more, because the fountain would blowout, but maybe a closer view would be better?', '2007-04-11 02:05:01.000000', NULL, 1),
(3537528, 493289, 39430, '<td valign="top">I nearly fell out of my chair when I saw this.  It''s hard to look at without falling over.  Nice job.  :)</td>', 'I nearly fell out of my chair when I saw this.  It''s hard to look at without falling over.  Nice job.  :)', '2007-04-11 02:05:52.000000', NULL, 1),
(3537536, 492894, 39430, '<td valign="top">Interesting shot.  I''d probably crop out the tower and bring out the towers more.  Also could do with some chroma noise reduction.</td>', 'Interesting shot.  I''d probably crop out the tower and bring out the towers more.  Also could do with some chroma noise reduction.', '2007-04-11 02:07:15.000000', NULL, 1),
(3537544, 495779, 39430, '<td valign="top">Nice detail.  Where''s the cheese?</td>', 'Nice detail.  Where''s the cheese?', '2007-04-11 02:11:46.000000', NULL, 1),
(3537545, 495339, 60862, '<td valign="top">Very sweet shot. :)</td>', 'Very sweet shot. :)', '2007-04-11 02:12:18.000000', NULL, 1),
(3537549, 496136, 39430, '<td valign="top">You''d probably have to use advanced editing to get a nice result from this shot.  As it is in basic editing, it''s just too dark and contrasty.</td>', 'You''d probably have to use advanced editing to get a nice result from this shot.  As it is in basic editing, it''s just too dark and contrasty.', '2007-04-11 02:12:52.000000', NULL, 1),
(3537553, 496128, 39430, '<td valign="top">Wow, nice dreamy effects.  The wind-blown tree really adds to it.  Great concept, and good work with the light painting on the tree.</td>', 'Wow, nice dreamy effects.  The wind-blown tree really adds to it.  Great concept, and good work with the light painting on the tree.', '2007-04-11 02:14:57.000000', NULL, 1),
(3537554, 494975, 39430, '<td valign="top">The negative space works well, but I would tend toward a slightly tighter crop.</td>', 'The negative space works well, but I would tend toward a slightly tighter crop.', '2007-04-11 02:16:12.000000', NULL, 1),
(3537557, 496052, 39430, '<td valign="top">Iceland is giving us a theme this week!  Awesome sky.  It''s a pity EVERYTHING is green.  Something artificially lit in the foreground would add some nice contrast.</td>', 'Iceland is giving us a theme this week!  Awesome sky.  It''s a pity EVERYTHING is green.  Something artificially lit in the foreground would add some nice contrast.', '2007-04-11 02:17:51.000000', NULL, 1),
(3537560, 496141, 39430, '<td valign="top">I don''t know if it''s focus or camera shake, but better focus would add a lot to this image.</td>', 'I don''t know if it''s focus or camera shake, but better focus would add a lot to this image.', '2007-04-11 02:18:40.000000', NULL, 1),
(3537566, 493900, 39430, '<td valign="top">Very dark, and no point of focus.  What are you trying to show in this photo?</td>', 'Very dark, and no point of focus.  What are you trying to show in this photo?', '2007-04-11 02:23:08.000000', NULL, 1),
(3537569, 495903, 39430, '<td valign="top">Interesting shot.  Good balance.  What are the streaks over the cross?  Is it snowing/raining?</td>', 'Interesting shot.  Good balance.  What are the streaks over the cross?  Is it snowing/raining?', '2007-04-11 02:24:02.000000', NULL, 1),
(3537570, 494865, 39430, '<td valign="top">Nice realistic colours.  Some sharpening and shadow curves would help this image really pop.</td>', 'Nice realistic colours.  Some sharpening and shadow curves would help this image really pop.', '2007-04-11 02:25:46.000000', NULL, 1),
(3537573, 495777, 39430, '<td valign="top">Yeah, she''s thinking "don''t just stand there taking photos, help ME!".  I imagine this was a tricky shot to get the white balance right.  I think a tighter crop, shallower DOF and sharping would all help here.</td>', 'Yeah, she''s thinking "don''t just stand there taking photos, help ME!".  I imagine this was a tricky shot to get the white balance right.  I think a tighter crop, shallower DOF and sharping would all help here.', '2007-04-11 02:28:12.000000', NULL, 1),
(3537576, 495363, 73747, '<td valign="top">Nice capture!</td>', 'Nice capture!', '2007-04-11 02:28:59.000000', NULL, 1),
(3537577, 494459, 39430, '<td valign="top">I like the silver and gold tones.  Too often these shots go orange, but the Gold works really well.  I''d even like to desat the blues to enhance this effect.</td>', 'I like the silver and gold tones.  Too often these shots go orange, but the Gold works really well.  I''d even like to desat the blues to enhance this effect.', '2007-04-11 02:29:25.000000', NULL, 1),
(3537578, 494945, 39430, '<td valign="top">I like the zoom effect, and these colours are full on!</td>', 'I like the zoom effect, and these colours are full on!', '2007-04-11 02:30:11.000000', NULL, 1),
(3537580, 495896, 39430, '<td valign="top">Nice composition.  A pity the highlights are blown and the shadows are so dark.  Try shooting raw if you can, and compress the tones.</td>', 'Nice composition.  A pity the highlights are blown and the shadows are so dark.  Try shooting raw if you can, and compress the tones.', '2007-04-11 02:31:38.000000', NULL, 1),
(3537582, 496118, 73747, '<td valign="top">Very visually appealing image.  What is causing the glow?  Is it a sunset or dusk photo, or a night photo?</td>', 'Very visually appealing image.  What is causing the glow?  Is it a sunset or dusk photo, or a night photo?', '2007-04-11 02:32:04.000000', NULL, 1),
(3537584, 493610, 73747, '<td valign="top">Beautiful image!</td>', 'Beautiful image!', '2007-04-11 02:33:53.000000', NULL, 1),
(3537585, 496116, 39430, '<td valign="top">This looks cool.  A little extra sharping would go a long way on this image.  Maybe a flash could have been used to bring out the tree better, instead of it being a silhouette.  Maybe a partial desat would have been better than a total black and white.  But still a striking image.</td>', 'This looks cool.  A little extra sharping would go a long way on this image.  Maybe a flash could have been used to bring out the tree better, instead of it being a silhouette.  Maybe a partial desat would have been better than a total black and white.  But still a striking image.', '2007-04-11 02:34:07.000000', NULL, 1),
(3537587, 496075, 39430, '<td valign="top">This is really cool.  The range of colours and shades in this image is great.  You did well to capture it all without resorting to advanced editing.  The scrappy rocks detract a little from the clean lines and colours of the bridges, and the left side doesn''t add anything to the image, but it''s still pretty amazing.</td>', 'This is really cool.  The range of colours and shades in this image is great.  You did well to capture it all without resorting to advanced editing.  The scrappy rocks detract a little from the clean lines and colours of the bridges, and the left side doesn''t add anything to the image, but it''s still pretty amazing.', '2007-04-11 02:36:38.000000', NULL, 1),
(3537588, 495708, 73747, '<td valign="top">Nice shot with the dark tree in the foreground and fading light to deep blues... makes it all an appealing image.  I wonder, tho, is this really night or dusk?</td>', 'Nice shot with the dark tree in the foreground and fading light to deep blues... makes it all an appealing image.  I wonder, tho, is this really night or dusk?', '2007-04-11 02:37:12.000000', NULL, 1),
(3537590, 494933, 39430, '<td valign="top">Nice mellow colours.  I like that the sky is actually darker than the water.  Did you use an ND filter for this?  Despite lacking in focus, it''s a great subtle image.</td>', 'Nice mellow colours.  I like that the sky is actually darker than the water.  Did you use an ND filter for this?  Despite lacking in focus, it''s a great subtle image.', '2007-04-11 02:37:59.000000', NULL, 1),
(3537593, 494044, 39430, '<td valign="top">What''s the mystery.  You can''t just leave us hanging!  Who dun it?</td>', 'What''s the mystery.  You can''t just leave us hanging!  Who dun it?', '2007-04-11 02:38:43.000000', NULL, 1),
(3537595, 492939, 73747, '<td valign="top">Pretty sunset... but isn''t this challenge for a night shot... not a sunset or at dusk?  Still like it tho!</td>', 'Pretty sunset... but isn''t this challenge for a night shot... not a sunset or at dusk?  Still like it tho!', '2007-04-11 02:39:57.000000', NULL, 1),
(3537599, 495664, 76198, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-04-11 02:40:21.000000', NULL, 1),
(3537600, 495989, 39430, '<td valign="top">Very dark and difficult to see any depth in the image.  It''s also difficult to work out what''s there (but I think I got it in the end.)  :)</td>', 'Very dark and difficult to see any depth in the image.  It''s also difficult to work out what''s there (but I think I got it in the end.)  :)', '2007-04-11 02:40:35.000000', NULL, 1),
(3537602, 495871, 76198, '<td valign="top">Wow. Surreal.</td>', 'Wow. Surreal.', '2007-04-11 02:41:10.000000', NULL, 1),
(3537605, 496092, 39430, '<td valign="top">Yup, that''s cold alright.  You could easily bump the highlights for a little more impact.</td>', 'Yup, that''s cold alright.  You could easily bump the highlights for a little more impact.', '2007-04-11 02:41:43.000000', NULL, 1),
(3537608, 496134, 39430, '<td valign="top">Nice clarity, but I''d prefer to see a much tighter crop on the statue, street and clock tower.</td>', 'Nice clarity, but I''d prefer to see a much tighter crop on the statue, street and clock tower.', '2007-04-11 02:42:47.000000', NULL, 1),
(3537610, 495590, 73747, '<td valign="top">Nice sunset image... crisp with soft colors and still water.  But wasn''t the challenge was for a night shot... not sunset or dusk?</td>', 'Nice sunset image... crisp with soft colors and still water.  But wasn''t the challenge was for a night shot... not sunset or dusk?', '2007-04-11 02:43:32.000000', NULL, 1),
(3537612, 495527, 39430, '<td valign="top">Freaky.  Looks like a UFO.  You could drop the shadows and give it a bit of noise reduction to improve the image.  Chroma noise is pretty nasty!</td>', 'Freaky.  Looks like a UFO.  You could drop the shadows and give it a bit of noise reduction to improve the image.  Chroma noise is pretty nasty!', '2007-04-11 02:44:01.000000', NULL, 1),
(3537621, 495163, 39430, '<td valign="top">Man, you should have gone much closer and taken a shot of the lava flow, maybe even stand in front for a snapshot.  Or better still make a little boat and row down the stream.  Oh, no wait, that could be dangerous.<br/> <br/>Seriously, the biggest negative about this shot is that I know the interesting stuff is just over the hill, but I CAN''T SEE IT!!!  :)</td>', 'Man, you should have gone much closer and taken a shot of the lava flow, maybe even stand in front for a snapshot.  Or better still make a little boat and row down the stream.  Oh, no wait, that could be dangerous. Seriously, the biggest negative about this shot is that I know the interesting stuff is just over the hill, but I CAN''T SEE IT!!!  :)', '2007-04-11 02:47:30.000000', NULL, 1),
(3537622, 493685, 73747, '<td valign="top">Somehow this seems to me to be completely lacking in the "wow factor" department.  Somebody gorked out in bed with their mouth open? I like the softness of the image and there seems to be very good coloring in the skin tones.</td>', 'Somehow this seems to me to be completely lacking in the "wow factor" department.  Somebody gorked out in bed with their mouth open? I like the softness of the image and there seems to be very good coloring in the skin tones.', '2007-04-11 02:47:46.000000', NULL, 1),
(3537624, 495702, 39430, '<td valign="top">The lack of focus is a little annoying.</td>', 'The lack of focus is a little annoying.', '2007-04-11 02:48:18.000000', NULL, 1),
(3537630, 494599, 39430, '<td valign="top">Ain''t it a bugger that AF doesn''t work well in the dark?  :)</td>', 'Ain''t it a bugger that AF doesn''t work well in the dark?  :)', '2007-04-11 02:49:41.000000', NULL, 1),
(3537632, 495903, 66201, '<td valign="top">Ah man you were standing in the rain too - pretty amazing sight though.</td>', 'Ah man you were standing in the rain too - pretty amazing sight though.', '2007-04-11 02:50:07.000000', NULL, 1),
(3537633, 495639, 76198, '<td valign="top">Hard when there''s nothing to focus on. I like the color and movement but wish something was clear...</td>', 'Hard when there''s nothing to focus on. I like the color and movement but wish something was clear...', '2007-04-11 02:50:25.000000', NULL, 1),
(3537634, 494624, 73747, '<td valign="top">If this is a legal editing process for this challenge, its great!</td>', 'If this is a legal editing process for this challenge, its great!', '2007-04-11 02:51:06.000000', NULL, 1),
(3537635, 496049, 39430, '<td valign="top">Nice colours and clarity.  It would be nicer to see one of these trees closer up.  It looks like they have lots of interesting textures in the gnarled trunks.</td>', 'Nice colours and clarity.  It would be nicer to see one of these trees closer up.  It looks like they have lots of interesting textures in the gnarled trunks.', '2007-04-11 02:51:35.000000', NULL, 1),
(3537638, 495593, 76198, '<td valign="top">Doesn''t look real. Really cool.</td>', 'Doesn''t look real. Really cool.', '2007-04-11 02:52:42.000000', NULL, 1),
(3537639, 495824, 39430, '<td valign="top">I''d work on the curves and colour balance for this shot.  Try taking out some cyan.</td>', 'I''d work on the curves and colour balance for this shot.  Try taking out some cyan.', '2007-04-11 02:53:19.000000', NULL, 1),
