(3541055, 494599, 1024, '<td valign="top">Unfortunately the egg is a little out of focus.  This is a great idea, and after the challenge, I would encourage you to experiment with it some more.</td>', 'Unfortunately the egg is a little out of focus.  This is a great idea, and after the challenge, I would encourage you to experiment with it some more.', '2007-04-11 21:48:16.000000', NULL, 1),
(3541058, 496113, 1024, '<td valign="top">Are those reactor towers?  This is a nice shot with alot of wonderful contrasts.  Well done.</td>', 'Are those reactor towers?  This is a nice shot with alot of wonderful contrasts.  Well done.', '2007-04-11 21:49:14.000000', NULL, 1),
