(3544591, 496136, 5347, '<td valign="top">Interesting leading lines.</td>', 'Interesting leading lines.', '2007-04-13 01:20:59.000000', NULL, 1),
(3544598, 495577, 5347, '<td valign="top">Centered subject does not work well in this image.  I think there is too much cut off at the bottom also.  Might have been nicer if the main area of the courthouse was almost full frame without those side pieces, they are distracting and un-interesting.</td>', 'Centered subject does not work well in this image.  I think there is too much cut off at the bottom also.  Might have been nicer if the main area of the courthouse was almost full frame without those side pieces, they are distracting and un-interesting.', '2007-04-13 01:23:27.000000', NULL, 1),
(3544599, 493144, 5347, '<td valign="top">Seems grainy and out-of-focus.</td>', 'Seems grainy and out-of-focus.', '2007-04-13 01:23:45.000000', NULL, 1),
(3544601, 494335, 5347, '<td valign="top">Interesting perspective.  Not a very interesting subject though, sorry.</td>', 'Interesting perspective.  Not a very interesting subject though, sorry.', '2007-04-13 01:24:18.000000', NULL, 1),
(3544603, 494221, 5347, '<td valign="top">This looks like the pattern on an old lady''s dress for some reason.  Almost like lace.</td>', 'This looks like the pattern on an old lady''s dress for some reason.  Almost like lace.', '2007-04-13 01:25:09.000000', NULL, 1),
(3544605, 492936, 5347, '<td valign="top">Not fond of the random-like movement.  There appears to be no distinct subject.</td>', 'Not fond of the random-like movement.  There appears to be no distinct subject.', '2007-04-13 01:25:51.000000', NULL, 1),
(3544607, 496108, 5792, '<td valign="top">Ahhh.. the Inner Harbor... probably the only safe place in Baltimore to take a picture at night. LOL!! ;) Nice view.</td>', 'Ahhh.. the Inner Harbor... probably the only safe place in Baltimore to take a picture at night. LOL!! ;) Nice view.', '2007-04-13 01:26:21.000000', NULL, 1),
