(3544760, 493685, 53316, '<td valign="top">I like the skin tones and the way the hair blends into the background.</td>', 'I like the skin tones and the way the hair blends into the background.', '2007-04-13 03:34:11.000000', NULL, 1),
(3544761, 494786, 49082, '<td valign="top">In my top few.</td>', 'In my top few.', '2007-04-13 03:35:41.000000', NULL, 1),
(3544763, 494456, 49082, '<td valign="top">There is a restaurant like this in my area, called the Marine Room. I love it!</td>', 'There is a restaurant like this in my area, called the Marine Room. I love it!', '2007-04-13 03:36:40.000000', NULL, 1),
(3544764, 495641, 53316, '<td valign="top">I like it overall, very interesting and captivating. I''d prefer the top lighter part be untextured. The texture that is there takes my eye away from the amazingly lovely textures at the bottom.<br/> <br/>Hm.  The thick-looking black layers reminds me of the room of shoes at the Holocaust Museum in Washington, DC.</td>', 'I like it overall, very interesting and captivating. I''d prefer the top lighter part be untextured. The texture that is there takes my eye away from the amazingly lovely textures at the bottom. Hm.  The thick-looking black layers reminds me of the room of shoes at the Holocaust Museum in Washington, DC.', '2007-04-13 03:36:46.000000', NULL, 1),
(3544765, 495639, 53316, '<td valign="top">Magical!!</td>', 'Magical!!', '2007-04-13 03:36:58.000000', NULL, 1),
