(3547905, 495365, 9690, '<td valign="top">Scary!  The direct flash is a bit offputting, but I don''t know of any other way to do it.  Escpecially if the racoon was wild.  But overall, a really great capture!</td>', 'Scary!  The direct flash is a bit offputting, but I don''t know of any other way to do it.  Escpecially if the racoon was wild.  But overall, a really great capture!', '2007-04-14 20:25:28.000000', NULL, 1),
(3547907, 493608, 9690, '<td valign="top">Interesting abstract.</td>', 'Interesting abstract.', '2007-04-14 20:25:48.000000', NULL, 1),
(3547911, 496101, 9690, '<td valign="top">Not all that interesting overall.  The action moves straight across the image, left to right.  That makes the picture one-dimensional.</td>', 'Not all that interesting overall.  The action moves straight across the image, left to right.  That makes the picture one-dimensional.', '2007-04-14 20:26:54.000000', NULL, 1),
(3547913, 494594, 9690, '<td valign="top">Very interesting, but too much concrete in the foreground.  I think this may have been a bit better if you could have elevated the camera a bit.  I like the depth and color, however.</td>', 'Very interesting, but too much concrete in the foreground.  I think this may have been a bit better if you could have elevated the camera a bit.  I like the depth and color, however.', '2007-04-14 20:27:47.000000', NULL, 1),
(3547916, 496142, 9690, '<td valign="top">The lights are over-exposed while the rest of the image is under-exposed.  Not much you can do about it in basic editing, though.</td>', 'The lights are over-exposed while the rest of the image is under-exposed.  Not much you can do about it in basic editing, though.', '2007-04-14 20:28:32.000000', NULL, 1),
(3547919, 494304, 9690, '<td valign="top">Very nice silhouette.  A welcome sight in comparison to the others I''ve seen so far.</td>', 'Very nice silhouette.  A welcome sight in comparison to the others I''ve seen so far.', '2007-04-14 20:29:04.000000', NULL, 1),
(3547926, 495497, 9690, '<td valign="top">I guess I am confused as to why you would do this in an image of a well known spot.  Why is the Washington monument in the image twice?  I don''t see it for the sake of art.</td>', 'I guess I am confused as to why you would do this in an image of a well known spot.  Why is the Washington monument in the image twice?  I don''t see it for the sake of art.', '2007-04-14 20:33:52.000000', NULL, 1),
(3547928, 494180, 9690, '<td valign="top">Very nice.  I love the contrast between the little church and the big city.  The grass looks very nice here too.  Great composition and angle.  With the exception of a couple of over-exposed areas, I think its near perfect.  9</td>', 'Very nice.  I love the contrast between the little church and the big city.  The grass looks very nice here too.  Great composition and angle.  With the exception of a couple of over-exposed areas, I think its near perfect.  9', '2007-04-14 20:35:11.000000', NULL, 1),
(3547930, 495590, 9690, '<td valign="top">Beautiful.  I love the depth (the rock in the foreground really adds to it) and the colors are terrific.  Great composition.  8</td>', 'Beautiful.  I love the depth (the rock in the foreground really adds to it) and the colors are terrific.  Great composition.  8', '2007-04-14 20:35:50.000000', NULL, 1),
(3547931, 493685, 9690, '<td valign="top">Interesting take.  The hand being so large and lit up in the foreground distracts, however.</td>', 'Interesting take.  The hand being so large and lit up in the foreground distracts, however.', '2007-04-14 20:36:27.000000', NULL, 1),
(3547932, 496108, 9690, '<td valign="top">Neat image.  Needs to be a bit sharper.</td>', 'Neat image.  Needs to be a bit sharper.', '2007-04-14 20:36:52.000000', NULL, 1),
(3547934, 495606, 9690, '<td valign="top">Great shot, but its a bit off-balanced.  The rock is strong, but the bridge on the right with nothing on the left of the image leads the eye right off the right side.  Balanced images will always do better.</td>', 'Great shot, but its a bit off-balanced.  The rock is strong, but the bridge on the right with nothing on the left of the image leads the eye right off the right side.  Balanced images will always do better.', '2007-04-14 20:38:06.000000', NULL, 1),
(3547935, 494174, 9690, '<td valign="top">Very eerie, but nice.  A bit grainy for a color shot, but overall a cool pic.</td>', 'Very eerie, but nice.  A bit grainy for a color shot, but overall a cool pic.', '2007-04-14 20:38:42.000000', NULL, 1),
(3547937, 493754, 9690, '<td valign="top">Soft, grainy, and tilted.  I am not sure what you were going for here.</td>', 'Soft, grainy, and tilted.  I am not sure what you were going for here.', '2007-04-14 20:39:08.000000', NULL, 1),
(3547938, 495651, 9690, '<td valign="top">Great capture of a moment.  I love the B&amp;W treatment, and the gritty surrealism here.  Great street candid. 8</td>', 'Great capture of a moment.  I love the B&W treatment, and the gritty surrealism here.  Great street candid. 8', '2007-04-14 20:39:55.000000', NULL, 1),
(3547939, 493980, 9690, '<td valign="top">Beautiful shot.  Great composition and depth... great coloring.  Perhaps a ribbon? 10</td>', 'Beautiful shot.  Great composition and depth... great coloring.  Perhaps a ribbon? 10', '2007-04-14 20:40:33.000000', NULL, 1),
(3547941, 495803, 9690, '<td valign="top">Hmmmmm. very soft, but in a pixelated way.</td>', 'Hmmmmm. very soft, but in a pixelated way.', '2007-04-14 20:41:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3547942, 495422, 9690, '<td valign="top">Neat shot.  Not very inspiring, however.</td>', 'Neat shot.  Not very inspiring, however.', '2007-04-14 20:41:28.000000', NULL, 1),
(3547948, 494542, 9690, '<td valign="top">Very quirky image!  I think there is no central focus, here, so too many things are competing for the eyes attention.</td>', 'Very quirky image!  I think there is no central focus, here, so too many things are competing for the eyes attention.', '2007-04-14 20:42:11.000000', NULL, 1),
(3547949, 494520, 9690, '<td valign="top">The left side of the house is over-exposedin relation to the rest of the image.  It stands out way to much from the rest of the home.</td>', 'The left side of the house is over-exposedin relation to the rest of the image.  It stands out way to much from the rest of the home.', '2007-04-14 20:43:02.000000', NULL, 1),
(3547953, 495137, 9690, '<td valign="top">Neat.  I think this is a great nature abstract.  Nice color, and the pattern created by the trees is cool.  I like how the whole image nearly fades off at the top.  I think it would be better without the star, quite honestly!</td>', 'Neat.  I think this is a great nature abstract.  Nice color, and the pattern created by the trees is cool.  I like how the whole image nearly fades off at the top.  I think it would be better without the star, quite honestly!', '2007-04-14 20:44:18.000000', NULL, 1),
(3547957, 496075, 9690, '<td valign="top">Beautiful shot!  Great depth and color!  It think the rocks in the foreground could stand to be a bit darker, however.  They compete with the bridge for the eyes'' attention. 9</td>', 'Beautiful shot!  Great depth and color!  It think the rocks in the foreground could stand to be a bit darker, however.  They compete with the bridge for the eyes'' attention. 9', '2007-04-14 20:45:17.000000', NULL, 1),
(3547958, 496136, 9690, '<td valign="top">Too much contrast between the dark and light areas.</td>', 'Too much contrast between the dark and light areas.', '2007-04-14 20:45:41.000000', NULL, 1),
(3547960, 495871, 54540, '<td valign="top">Phenomenal!  Caught my eye already, as I was perusing the thumbs!<br/>I like the choice you made to turn night into day (levels / colors / saturation I presume)<br/> <br/>Good luck in the challenge!</td>', 'Phenomenal!  Caught my eye already, as I was perusing the thumbs!I like the choice you made to turn night into day (levels / colors / saturation I presume) Good luck in the challenge!', '2007-04-14 20:45:48.000000', NULL, 1),
(3547961, 495689, 54540, '<td valign="top">Excellent lightning capture!  Very good composition too.  One of my top picks.</td>', 'Excellent lightning capture!  Very good composition too.  One of my top picks.', '2007-04-14 20:45:58.000000', NULL, 1),
(3547964, 494940, 9690, '<td valign="top">Interesting.  Ultimately, this shot would be nice with some increased contrast and maybe some vignetting (not legal in basic, I think).</td>', 'Interesting.  Ultimately, this shot would be nice with some increased contrast and maybe some vignetting (not legal in basic, I think).', '2007-04-14 20:46:43.000000', NULL, 1),
