(3547969, 494489, 9690, '<td valign="top">Beautiful shot.  Great exposure and colors.  8</td>', 'Beautiful shot.  Great exposure and colors.  8', '2007-04-14 20:48:44.000000', NULL, 1),
(3547972, 495339, 9690, '<td valign="top">Nice and refreshing take on the challenge.  Great lighting, exposure, and very emotive.  Reminds me of the last verse of "Summer Breeze."  I really hope this ribbons for its excellent photographic qualities and your innovative spirit.  10</td>', 'Nice and refreshing take on the challenge.  Great lighting, exposure, and very emotive.  Reminds me of the last verse of "Summer Breeze."  I really hope this ribbons for its excellent photographic qualities and your innovative spirit.  10', '2007-04-14 20:50:46.000000', NULL, 1),
(3547975, 495314, 9690, '<td valign="top">Beautiful shot.  Great take on the challenge  9</td>', 'Beautiful shot.  Great take on the challenge  9', '2007-04-14 20:51:54.000000', NULL, 1),
(3547977, 494276, 9690, '<td valign="top">Simply beautiful.  A great testament to God''s creation.</td>', 'Simply beautiful.  A great testament to God''s creation.', '2007-04-14 20:52:59.000000', NULL, 1),
