(3549140, 496035, 45115, '<td valign="top">great!</td>', 'great!', '2007-04-15 12:15:32.000000', NULL, 1),
(3549145, 496026, 65234, '<td valign="top">Certainly minimalist.  Personally I might have found it more interesting if the foreground were not brightly lit and I could see just a bit more of that solitary silhouetted person (I think it''s a person) in the house.</td>', 'Certainly minimalist.  Personally I might have found it more interesting if the foreground were not brightly lit and I could see just a bit more of that solitary silhouetted person (I think it''s a person) in the house.', '2007-04-15 12:17:10.000000', NULL, 1),
(3549146, 494489, 65234, '<td valign="top">Amazing detail and color and the star effect on the lights is lovely.  Excellent job!</td>', 'Amazing detail and color and the star effect on the lights is lovely.  Excellent job!', '2007-04-15 12:17:51.000000', NULL, 1),
(3549148, 496096, 65234, '<td valign="top">Interesting perspective.  Not sure why the building is warped ... maybe to make it look like it''s leaning toward the one bright light we can see?</td>', 'Interesting perspective.  Not sure why the building is warped ... maybe to make it look like it''s leaning toward the one bright light we can see?', '2007-04-15 12:19:40.000000', NULL, 1),
(3549150, 496073, 45115, '<td valign="top">EXCELLENT!!! I hope this will win!</td>', 'EXCELLENT!!! I hope this will win!', '2007-04-15 12:20:37.000000', NULL, 1),
(3549151, 496043, 65234, '<td valign="top">Interesting; makes me want to see it again on a warm summer night.  Nice subtle lighting making me wonder if we could just turn and see an old-fashioned back porch, and the clouds definitely add to the composition.</td>', 'Interesting; makes me want to see it again on a warm summer night.  Nice subtle lighting making me wonder if we could just turn and see an old-fashioned back porch, and the clouds definitely add to the composition.', '2007-04-15 12:23:05.000000', NULL, 1),
(3549155, 496103, 65234, '<td valign="top">Creative; that''s a playground, isn''t it?  Like the perspective and colors, even though the purple is a little otherwordly.</td>', 'Creative; that''s a playground, isn''t it?  Like the perspective and colors, even though the purple is a little otherwordly.', '2007-04-15 12:24:27.000000', NULL, 1),
(3549156, 495382, 65234, '<td valign="top">Sorry; even as an abstract this doesn''t do anything for me.  Maybe needs more contrast as a start?</td>', 'Sorry; even as an abstract this doesn''t do anything for me.  Maybe needs more contrast as a start?', '2007-04-15 12:26:19.000000', NULL, 1),
(3549158, 494937, 65234, '<td valign="top">Lovely composition and I''m impressed to see stars over a city-type building which was clearly lit.</td>', 'Lovely composition and I''m impressed to see stars over a city-type building which was clearly lit.', '2007-04-15 12:27:19.000000', NULL, 1),
(3549161, 494617, 65234, '<td valign="top">Soft and beautiful; has a dreamlike quality to it.</td>', 'Soft and beautiful; has a dreamlike quality to it.', '2007-04-15 12:28:39.000000', NULL, 1),
(3549164, 494706, 65234, '<td valign="top">Good idea for this challenge.  On my monintor this looks like it has too much light: sky and water are muddy instead of dark and lights on the house in the water are blown out which is amplified by their reflection.</td>', 'Good idea for this challenge.  On my monintor this looks like it has too much light: sky and water are muddy instead of dark and lights on the house in the water are blown out which is amplified by their reflection.', '2007-04-15 12:31:11.000000', NULL, 1),
(3549168, 496057, 65234, '<td valign="top">Great "make the view feel like he''s there" image!  Looks like Camden Yards, but then lots of the newer ballparks look alike.  Fun shot.</td>', 'Great "make the view feel like he''s there" image!  Looks like Camden Yards, but then lots of the newer ballparks look alike.  Fun shot.', '2007-04-15 12:34:27.000000', NULL, 1),
(3549172, 495497, 65234, '<td valign="top">Certainly not a standard DC shot ;-)  Can''t wait to see the details; you''ve definitely created a pretty, balanced night scene.</td>', 'Certainly not a standard DC shot ;-)  Can''t wait to see the details; you''ve definitely created a pretty, balanced night scene.', '2007-04-15 12:41:01.000000', NULL, 1),
(3549177, 495390, 65234, '<td valign="top">I like the inclusion of the cherry tree in the photo.  Nice detail in this one.</td>', 'I like the inclusion of the cherry tree in the photo.  Nice detail in this one.', '2007-04-15 12:45:39.000000', NULL, 1),
(3549183, 495700, 65234, '<td valign="top">Great effect with the dueling lights and the solitary guy in the cowboy hat.  Tone and composition appeal to my imagination :-)</td>', 'Great effect with the dueling lights and the solitary guy in the cowboy hat.  Tone and composition appeal to my imagination :-)', '2007-04-15 12:48:47.000000', NULL, 1),
(3549291, 496002, 57584, '<td valign="top">GORGEOUS!!</td>', 'GORGEOUS!!', '2007-04-15 13:37:57.000000', NULL, 1),
