(3551997, 494923, 47470, '<td valign="top">Beautifully executed, but I had to drop it to a nine because, although it is gorgeous, it is like most postcards of the same scene.  It needs something to make it stand out from the rest(but it did stand out from the others in this competition)!</td>', 'Beautifully executed, but I had to drop it to a nine because, although it is gorgeous, it is like most postcards of the same scene.  It needs something to make it stand out from the rest(but it did stand out from the others in this competition)!', '2007-04-16 12:51:11.000000', NULL, 1),
(3552017, 495564, 47470, '<td valign="top">The brightly light scene with the stars in the background make for an interesting photo, but I think I wold have liked to darken the forground just a bit to make the stars stand out more.</td>', 'The brightly light scene with the stars in the background make for an interesting photo, but I think I wold have liked to darken the forground just a bit to make the stars stand out more.', '2007-04-16 12:56:19.000000', NULL, 1),
(3552041, 496046, 75386, '<td valign="top">wow, I had no idea they looked like that! great photo</td>', 'wow, I had no idea they looked like that! great photo', '2007-04-16 13:06:15.000000', NULL, 1),
(3552043, 495639, 47470, '<td valign="top">I like the colors, but the subject is a bit too chaotic.</td>', 'I like the colors, but the subject is a bit too chaotic.', '2007-04-16 13:06:58.000000', NULL, 1),
