(3552052, 494809, 75386, '<td valign="top">very classy and noir.  I just like it</td>', 'very classy and noir.  I just like it', '2007-04-16 13:10:42.000000', NULL, 1),
(3552053, 495422, 47470, '<td valign="top">I think I would have cropped out a bit more sky.  Even though it is done with the rule of thirds between buildings and sky, I would have put the line separating the facade from the roofs on the upper line of thirds and maybe even kept a little more ground.  Pretty shot regardless!</td>', 'I think I would have cropped out a bit more sky.  Even though it is done with the rule of thirds between buildings and sky, I would have put the line separating the facade from the roofs on the upper line of thirds and maybe even kept a little more ground.  Pretty shot regardless!', '2007-04-16 13:11:07.000000', NULL, 1),
(3552058, 495597, 75386, '<td valign="top">they usually dont mean that when they say that expression... :/</td>', 'they usually dont mean that when they say that expression... :/', '2007-04-16 13:12:20.000000', NULL, 1),
(3552062, 493980, 75386, '<td valign="top">Surreal, where is this?  I like it!</td>', 'Surreal, where is this?  I like it!', '2007-04-16 13:13:42.000000', NULL, 1),
(3552094, 495700, 47470, '<td valign="top">I like this picture, but maybe a different white balance would have given a better color (I''m not much a fan of the nighttime yellow-orange light).</td>', 'I like this picture, but maybe a different white balance would have given a better color (I''m not much a fan of the nighttime yellow-orange light).', '2007-04-16 13:26:58.000000', NULL, 1),
(3552105, 494276, 47470, '<td valign="top">Very pretty!  I might have darkened the picture ever so slightly to make the stars stand out.  But nice colors!</td>', 'Very pretty!  I might have darkened the picture ever so slightly to make the stars stand out.  But nice colors!', '2007-04-16 13:29:10.000000', NULL, 1),
(3552115, 495975, 47470, '<td valign="top">So many light bursts!  They have a nice shape though.  The blue on the top of the tower seems a bit out of place, but I like this picture.</td>', 'So many light bursts!  They have a nice shape though.  The blue on the top of the tower seems a bit out of place, but I like this picture.', '2007-04-16 13:30:59.000000', NULL, 1),
(3552124, 494464, 47470, '<td valign="top">Great colors and wonderful idea!</td>', 'Great colors and wonderful idea!', '2007-04-16 13:32:31.000000', NULL, 1);
